'use client';

import { useState } from 'react';
import { Button, Field, PageHeader, Panel, Tag } from '@/components/ui';

/**
 * A local preview of an ad card from what you type. Nothing is generated by AI or
 * published: those parts are coming soon and their controls are disabled.
 */
export default function MarketingStudioPage() {
  const [headline, setHeadline] = useState('Hire Top 1% Pre-Vetted Systems Engineers');
  const [targetRole, setTargetRole] = useState('Senior Distributed Systems Engineer');

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
      <PageHeader
        eyebrow="Growth & Marketing"
        title="Ad Studio"
        sub="Draft a hiring ad and preview how it reads."
      />

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '16px' }}>
        <Panel style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <h3 style={{ margin: 0, fontSize: '1rem', fontWeight: 600 }}>Creative Configurator</h3>
          <Field label="Target Role">
            <input type="text" value={targetRole} onChange={(e) => setTargetRole(e.target.value)} />
          </Field>
          <Field label="Headline">
            <input type="text" value={headline} onChange={(e) => setHeadline(e.target.value)} />
          </Field>
          <Button variant="mint" disabled>
            Generate with AI (coming soon)
          </Button>
          <p style={{ margin: 0, fontSize: '0.8rem', color: 'var(--fg-3)' }}>
            The preview updates as you type. AI generation and publishing are coming soon; nothing is saved or posted.
          </p>
        </Panel>

        <Panel style={{ display: 'flex', flexDirection: 'column', gap: '12px', background: 'linear-gradient(135deg, rgba(20, 24, 38, 0.9), rgba(12, 14, 24, 0.95))', border: '1px solid var(--blue)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: '0.75rem', color: 'var(--blue)', fontWeight: 600, textTransform: 'uppercase' }}>Preview: social card</span>
            <Tag color="grey">Draft</Tag>
          </div>
          <h2 style={{ margin: '8px 0', fontSize: '1.3rem', color: '#fff' }}>{headline}</h2>
          <p style={{ margin: 0, fontSize: '0.85rem', color: 'var(--fg-2)' }}>
            Hiring: {targetRole}. Candidates are assessed on reasoning, team EQ and persistence.
          </p>
        </Panel>
      </div>
    </div>
  );
}
